      return {{ x: p.x, y: y, source: 'plotly_click' }};
    }}
    function axisValue(axis, pixel) {{
      if (!axis) return null;
      if (typeof axis.p2d === 'function') return axis.p2d(pixel);
      if (typeof axis.p2c === 'function') return axis.p2c(pixel);
