          yref: 'y',
          x0: xs[0],
          x1: xs[1],
          y0: point.y,
          y1: point.y,
          line: line,
          layer: 'above'
        }});
        shapes.push({{
          type: 'circle',
          name: name + '-ring',
          xref: 'x',
          yref: 'y',
          x0: xs[0],
          x1: xs[1],
          y0: ys[0],
          y1: ys[1],
